<template><div class="wrap"><div ref="chartRef" class="chart"></div><el-table :data="scores" size="small" border><el-table-column prop="name" label="能力"/><el-table-column prop="score" label="候选人"/><el-table-column prop="targetScore" label="岗位目标"/><el-table-column label="差距"><template #default="{row}"><span :class="row.gap>=0?'good':'gap'">{{ row.gap>0?'+':'' }}{{ row.gap }}</span></template></el-table-column><el-table-column label="结论"><template #default="{row}"><el-tag :type="row.status==='达标'?'success':'warning'">{{ row.status }}</el-tag></template></el-table-column></el-table></div></template>
<script setup>import {nextTick,onBeforeUnmount,onMounted,ref,watch} from "vue";import * as echarts from "echarts";const props=defineProps({scores:{type:Array,default:()=>[]}});const chartRef=ref(null);let chart;const draw=async()=>{await nextTick();if(!chartRef.value||!props.scores.length)return;chart ||= echarts.init(chartRef.value);chart.setOption({tooltip:{},legend:{data:["候选人得分","岗位目标线"],bottom:0},radar:{radius:"65%",indicator:props.scores.map(i=>({name:i.name,max:100}))},series:[{type:"radar",data:[{name:"候选人得分",value:props.scores.map(i=>i.score),areaStyle:{opacity:.2}},{name:"岗位目标线",value:props.scores.map(i=>i.targetScore),lineStyle:{type:"dashed"}}]}]})};const resize=()=>chart?.resize();onMounted(()=>{draw();window.addEventListener("resize",resize)});watch(()=>props.scores,draw,{deep:true});onBeforeUnmount(()=>{window.removeEventListener("resize",resize);chart?.dispose()});</script>
<style scoped>.chart{height:390px}.good{color:#67c23a}.gap{color:#e6a23c;font-weight:600}</style>
